"""`total()` 现有行为的防回归测试：免税、只打折、只计税。"""

from pricing import total


def test_regression_tax_free_region():
    assert total([(2, 19.99), (1, 4.5)], region="none") == 44.48


def test_regression_discount_without_tax():
    assert total([(1, 100.0)], region="none", discount=0.10) == 90.0


def test_regression_tax_without_discount():
    assert total([(1, 80.0)], region="uk") == 96.0
